import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Filter for the specific dataset by name
filter = {"name": "SmartSPIM_675387_2023-05-23_23-05-56"}

# Project only the subject procedures field which contains injection information
projection = {
    "procedures.subject_procedures": 1
}

records = docdb_api_client.retrieve_docdb_records(
    filter_query=filter,
    projection=projection,
)

# Extract and format the injection information more clearly
if records:
    injections = []
    for record in records:
        if "procedures" in record and "subject_procedures" in record["procedures"]:
            for subject_procedure in record["procedures"]["subject_procedures"]:
                if "procedures" in subject_procedure:
                    for procedure in subject_procedure["procedures"]:
                        if "injection_materials" in procedure:
                            injection_info = {
                                "date": subject_procedure.get("start_date"),
                                "procedure_type": procedure.get("procedure_type"),
                                "material": [material.get("name") for material in procedure.get("injection_materials", [])],
                                "targeted_structure": procedure.get("targeted_structure"),
                                "hemisphere": procedure.get("injection_hemisphere"),
                                "coordinates": {
                                    "ml": procedure.get("injection_coordinate_ml"),
                                    "ap": procedure.get("injection_coordinate_ap"),
                                    "depth": procedure.get("injection_coordinate_depth")
                                },
                                "volume": procedure.get("injection_volume"),
                                "volume_unit": procedure.get("injection_volume_unit")
                            }
                            injections.append(injection_info)

    print(json.dumps(injections, indent=3))
else:
    print("No records found for SmartSPIM_675387_2023-05-23_23-05-56")

