DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Create an aggregation pipeline to find animals in the "Thalamus in the middle" project
# with injections at coordinates AP: 2.8, ML: 0.2, DV: 0.6
agg_pipeline = [
    {
        "$match": {
            "data_description.project_name": "Thalamus in the middle",
            "procedures.subject_procedures": {
                "$elemMatch": {
                    "procedures": {
                        "$elemMatch": {
                            "injection_coordinate_ap": 2.8,
                            "injection_coordinate_ml": 0.2,
                            "injection_coordinate_depth": 0.6
                        }
                    }
                }
            }
        }
    },
    {
        "$count": "number_of_animals"
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)
print(json.dumps(result, indent=3))

# Let's also check the actual records to verify
agg_pipeline_records = [
    {
        "$match": {
            "data_description.project_name": "Thalamus in the middle",
            "procedures.subject_procedures": {
                "$elemMatch": {
                    "procedures": {
                        "$elemMatch": {
                            "injection_coordinate_ap": 2.8,
                            "injection_coordinate_ml": 0.2,
                            "injection_coordinate_depth": 0.6
                        }
                    }
                }
            }
        }
