                    "as": "proc",
                    "cond": {
                        "$and": [
                            {"$eq": [{"$anyElementTrue": {"$map": {"input": "$$proc", "as": "p", "in": {"$and": [
                                {"$eq": ["$$p.injection_coordinate_ap", 2.8]},
                                {"$eq": ["$$p.injection_coordinate_ml", 0.2]},
                                {"$eq": ["$$p.injection_coordinate_depth", 0.6]}
                            ]}}}}, True]}
                        ]
                    }
                }
            }
        }
    },
    {
        "$limit": 5
    }
]

sample_records = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline_records
)
print("\nSample records (limited to 5):")
print(json.dumps(sample_records, indent=3))

