import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find subjects with sessions containing both optical physiology and behavior data streams
agg_pipeline = [
    # Match documents that have a session field
    {"$match": {"session": {"$exists": True, "$ne": None}}},

    # Project only the fields we need
    {"$project": {
        "subject_id": "$subject.subject_id",
        "session_data_streams": "$session.data_streams"
    }},

    # Filter out documents with missing subject_id or session_data_streams
    {"$match": {
        "subject_id": {"$exists": True, "$ne": None},
        "session_data_streams": {"$exists": True, "$ne": None}
    }},

    # Unwind the data_streams array to process each stream individually
    {"$unwind": "$session_data_streams"},

    # Group by subject_id and collect unique modalities
    {"$group": {
        "_id": "$subject_id",
        "modalities": {"$addToSet": "$session_data_streams.modality"}
    }},

    # Filter for subjects that have both optical physiology and behavior modalities
    {"$match": {
        "modalities": {"$all": ["optical physiology", "behavior"]}
    }},

    # Count the number of subjects
    {"$count": "subjects_with_both_modalities"}
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)

print(json.dumps(result, indent=3))

