import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Filter for the specific asset by name
filter = {"name": "SmartSPIM_692908_2023-11-08_16-48-13_stitched_2023-11-09_11-12-06"}

# Project only the channel information
projection = {
    "acquisition.tiles.channel": 1,
    "_id": 0
}

records = docdb_api_client.retrieve_docdb_records(
    filter_query=filter,
    projection=projection,
)

# Extract unique channels from the results
channels = []
for record in records:
    if "acquisition" in record and "tiles" in record["acquisition"]:
        for tile in record["acquisition"]["tiles"]:
            if "channel" in tile:
                # Check if the channel is a dictionary or a simple value
                channel_value = tile["channel"]
                if isinstance(channel_value, dict):
                    # If it's a dictionary, convert to string representation for uniqueness
                    channel_str = json.dumps(channel_value, sort_keys=True)
                    if channel_str not in channels:
                        channels.append(channel_str)
                else:
                    # If it's a simple value, add directly if not already in the list
                    if channel_value not in channels:
                        channels.append(channel_value)

print("Channels imaged in asset SmartSPIM_692908_2023-11-08_16-48-13_stitched_2023-11-09_11-12-06:")
if channels:
    # Convert any JSON strings back to dictionaries for display
    display_channels = []
    for channel in channels:
        if channel.startswith('{') and channel.endswith('}'):
            try:
                display_channels.append(json.loads(channel))
            except:
                display_channels.append(channel)
        else:
            display_channels.append(channel)
    print(display_channels)
else:
    print("No channel information found")

print("\nRaw query results:")
print(json.dumps(records, indent=3))

